// Generated by ruse-mcp from the graph in manifest.json. Change the plugin through set_graph, not this file.
//! The signal path of Multiband Compressor is a graph of blocks. The graph is data: it is in manifest.json and is read here
//! when the plugin is made. Nothing in this file needs writing by hand.

use crate::Params;
use ruse_blocks::Graph;
use ruse_core::{ProcessContext, Setup};

const GRAPH: &str = r#"{"bypass":"bypass","mix":"mix","chain":[{"split":{"freqs":["low_cross","high_cross"],"slope":24,"bands":[{"block":"dynamics","args":{"threshold_db":"low_threshold","ratio":"ratio","attack_ms":"attack","release_ms":"release"},"meters":{"gain_reduction_db":"gr_low"}},{"block":"dynamics","args":{"threshold_db":"mid_threshold","ratio":"ratio","attack_ms":"attack","release_ms":"release"},"meters":{"gain_reduction_db":"gr_mid"}},{"block":"dynamics","args":{"threshold_db":"high_threshold","ratio":"ratio","attack_ms":"attack","release_ms":"release"},"meters":{"gain_reduction_db":"gr_high"}}]}},{"block":"gain","args":{"gain_db":"output"}}]}"#;

pub struct State {
    graph: Graph,
}

impl State {
    pub fn new() -> Self {
        let ids: Vec<&str> = crate::PARAMS.iter().map(|p| p.id).collect();
        State {
            graph: Graph::from_str(GRAPH, &ids).expect("the graph was checked against the parameters when it was set"),
        }
    }

    pub fn prepare(&mut self, setup: &Setup) {
        self.graph.prepare(setup);
    }

    pub fn latency_samples(&self) -> u32 {
        self.graph.latency_samples()
    }

    /// How long the plugin keeps sounding after its input stops, at the parameters' current values.
    pub fn tail_samples(&self, p: &Params) -> u32 {
        self.graph.tail_for(p.set())
    }

    pub fn process(&mut self, p: &Params, channels: &mut [&mut [f32]], ctx: &ProcessContext) {
        self.graph.process(p.set(), channels, ctx);
    }

    /// The same, with the sidechain for the same samples. Only a graph that listens to a sidechain has one.
    pub fn process_with_sidechain(&mut self, p: &Params, channels: &mut [&mut [f32]], sidechain: &[&[f32]], ctx: &ProcessContext) {
        self.graph.process_with_sidechain(p.set(), channels, sidechain, ctx);
    }
}

impl Default for State {
    fn default() -> Self {
        Self::new()
    }
}
